        return false;
    player->ApplyRatingMod(CR_HASTE_MELEE, Value, true);
    player->ApplyRatingMod(CR_HASTE_RANGED, Value, true);
    player->ApplyRatingMod(CR_HASTE_SPELL, Value, true);
    return true;
}

